<script setup>
import {ref,computed,onUnmounted,watch} from 'vue';import BaseModal from '../components/BaseModal.vue';import {state,company,api,scope,useResource,notify,changed,ask} from '../lib/workspace';
import {can,allowedApi,writable} from '../lib/workspace';import {amount,money,uid} from '../lib/format';
import {captureContext,contextMatches} from '../lib/workspace';
import {prepareEntries,declaredBase,compatibleRules,entriesPayload} from '../lib/assessment-preparation.js';
import {useSuggestedCompetence} from '../lib/context-preferences.js';
const competence=ref(state.period);useSuggestedCompetence(state,competence);
const tax=ref('icms'),show=ref(false),mode=ref('assessment'),form=ref({}),context=ref({}),error=ref(''),busy=ref(false),detail=ref(null);let baseline='',generation=0;const preview=ref(null),page=ref(1),common=ref({effect:'',reason:'',rule_id:''});
const selectedCount=computed(()=>form.value.entries?.filter(e=>e.selected!==false).length||0);
const pageCount=computed(()=>Math.max(1,Math.ceil((form.value.entries?.length||0)/50)));
const visibleEntries=computed(()=>form.value.entries?.slice((page.value-1)*50,page.value*50)||[]);
const finalized=computed(()=>data.value.ledgers.some(l=>!l.reversed_at&&l.tax===tax.value));
watch(form,()=>{preview.value=null;},{deep:true,flush:'sync'});
watch(()=>[state.companyId,state.period.slice(0,4),state.module],()=>{generation++;show.value=false;detail.value=null;preview.value=null;busy.value=false;if(state.editor?.owner==='assessment')state.editor=null;},{flush:'sync'});
const {data,error:loadError,loading:loadingData,reload}=useResource(async()=>{if(!state.companyId)return {documents:[],rules:[],assessments:[],adjustments:[],ledgers:[]};const [documents,rules,assessments,adjustments,ledgers]=await Promise.all([allowedApi('fiscal.documents',scope(`/documents?period=${competence.value}`)),allowedApi('fiscal.parameters',scope('/rules')),api(scope(`/assessments?period=${competence.value}`)),api(scope(`/tax-adjustments?period=${competence.value}`)),api(scope(`/tax-ledgers?period=${competence.value}`))]);return {documents,rules,assessments,adjustments,ledgers};},{documents:[],rules:[],assessments:[],adjustments:[],ledgers:[]});
watch(competence,()=>{if(!show.value)reload()});
const rules=computed(()=>data.value.rules.filter(r=>r.tax.toLowerCase()===tax.value&&r.status==='validated'&&r.active&&!r.superseded_by));
function payload(){return {tax:form.value.tax,period:context.value.period,idempotency_key:form.value.idempotency_key,opening_mode:form.value.opening_mode,opening_reason:form.value.opening_reason,opening_credit:amount(form.value.opening_credit),no_movement_confirmed:form.value.no_movement_confirmed,source:form.value.source,responsible:form.value.responsible,entries:entriesPayload(form.value.entries,amount)};}
async function open(type='assessment'){
 if(busy.value||state.editor||state.confirm||state.contextBusy||loadingData.value||!state.companyId||loadError.value||finalized.value||!writable('fiscal.assessments','create',competence.value))return;
 const token=++generation;busy.value=true;preview.value=null;page.value=1;common.value={effect:'',reason:'',rule_id:''};mode.value=type;
 context.value={id:state.companyId,name:company.value.name,period:competence.value,request:captureContext()};
 form.value={tax:tax.value,period:competence.value,idempotency_key:uid(),opening_mode:'previous',opening_reason:'',no_movement_confirmed:false,opening_credit:'0,00',source:'',responsible:'',entries:[],kind:'debit',category:'other',amount:'',reason:''};
 show.value=true;error.value='';state.editor={owner:'assessment',name:'Preparar apuração',companyId:state.companyId};
 try{if(type==='assessment'){form.value.entries=prepareEntries(data.value.documents,rules.value,tax.value,company.value,competence.value);const previous=await api(scope(`/tax-ledgers/previous?period=${context.value.period}&tax=${tax.value}`,context.value.id));if(token!==generation)return;form.value.previous=previous;}}
 catch(e){if(token===generation)error.value=e.message;}
 finally{if(token===generation){baseline=JSON.stringify(form.value);busy.value=false;}}
}
async function close(){if(busy.value||state.confirm)return;if(baseline!==JSON.stringify(form.value)&&!await ask({title:'Descartar edição?',message:'A memória ainda não foi registrada.',confirmLabel:'Descartar'}))return;generation++;show.value=false;preview.value=null;if(state.editor?.owner==='assessment')state.editor=null;}
async function confer(){if(busy.value)return;const token=generation;busy.value=true;error.value='';preview.value=null;try{const result=await api(scope('/assessments/preview',context.value.id),{method:'POST',context:context.value.request,body:payload()});if(token===generation)preview.value=result;}catch(e){if(token===generation)error.value=e.message;}finally{if(token===generation)busy.value=false;}}
async function save(){
 if(busy.value||(mode.value==='assessment'&&!preview.value))return;const token=generation;busy.value=true;error.value='';
 try{const p=mode.value==='assessment'?{...payload(),preview_fingerprint:preview.value.fingerprint,coverage_fingerprint:preview.value.coverage.fingerprint}:{tax:form.value.tax,period:context.value.period,idempotency_key:form.value.idempotency_key,kind:form.value.kind,category:form.value.category,amount:amount(form.value.amount),source:form.value.source,reason:form.value.reason};
 const result=await api(scope(mode.value==='assessment'?'/assessments':'/tax-adjustments',context.value.id),{method:'POST',context:context.value.request,body:p});if(token!==generation)return;
 show.value=false;state.editor=null;preview.value=null;changed();if(result.snapshot)detail.value=result;notify('Registro fiscal salvo. Finalização permanece separada.');
 }catch(e){if(token===generation){preview.value=null;error.value=e.message;}}finally{if(token===generation)busy.value=false;}
}
function applyCommon(){if(busy.value)return;for(const entry of form.value.entries.filter(e=>e.selected!==false)){if(common.value.effect)entry.effect=common.value.effect;if(common.value.reason.trim())entry.reason=common.value.reason.trim();if(common.value.rule_id)entry.rule_id=common.value.rule_id;}}
async function balanceOnly(){if(busy.value||state.confirm)return;if(form.value.entries.length&&!await ask({title:'Usar somente ajustes e saldo anterior?',message:'As bases do rascunho serão retiradas. Nenhum documento ou memória salva será alterado.',confirmLabel:'Retirar bases do rascunho'}))return;form.value.entries=[];form.value.no_movement_confirmed=false;page.value=1;}
function changeDocument(entry){const d=data.value.documents.find(d=>d.id===entry.document_id);entry.item_indices=[];entry.base=d?declaredBase(d,form.value.tax):'';const available=d?compatibleRules(d,rules.value,form.value.tax,company.value):[];entry.rule_id=available.length===1?available[0].id:'';entry.effect='';entry.reason='';}
async function runAction(fn){if(busy.value||state.editor||state.confirm||state.contextBusy)return;const token=++generation;busy.value=true;state.editor={owner:'assessment',name:'Operação fiscal',companyId:state.companyId};try{await fn();}finally{if(token===generation){busy.value=false;if(state.editor?.owner==='assessment')state.editor=null;}}}
const reverse=a=>runAction(()=>doReverse(a)),finalize=a=>runAction(()=>doFinalize(a)),undoLedger=a=>runAction(()=>doUndoLedger(a));
async function doReverse(a){const request=captureContext(),cid=state.companyId,p=competence.value;const reason=await ask({title:'Estornar ajuste fiscal',message:'O ajuste será preservado no histórico e deixará de compor as próximas memórias.',inputLabel:'Justificativa',required:true,confirmLabel:'Estornar ajuste'});if(!reason||!contextMatches(request))return;try{await api(scope(`/tax-adjustments/${a.id}/reverse`,cid),{method:'POST',context:request,body:{reason,period:p}});changed();}catch(e){notify(e.message,'error');}}
async function doFinalize(a){const request=captureContext(),cid=state.companyId,p=competence.value;const reason=await ask({title:'Finalizar apuração revisada',message:'Confirme que todos os documentos, bases, não incidências, créditos e ajustes deste tributo foram revisados. A finalização protege suas bases e disponibiliza o saldo ao mês seguinte; não gera guia, título financeiro ou transmissão.',inputLabel:'Justificativa da revisão integral',required:true,confirmLabel:'Confirmar revisão e finalizar'});if(!reason||!contextMatches(request))return;try{await api(scope(`/assessments/${a.id}/finalize`,cid),{method:'POST',context:request,body:{period:p,reason,coverage_reviewed:true,idempotency_key:uid()}});changed();notify('Apuração finalizada. Saldo disponível para transporte no mesmo tributo.');}catch(e){notify(e.message,'error');}}
async function doUndoLedger(a){const request=captureContext(),cid=state.companyId,p=competence.value;const reason=await ask({title:'Reverter finalização',message:'A memória será preservada. Apurações posteriores do mesmo tributo devem ser revertidas primeiro.',inputLabel:'Justificativa',required:true,confirmLabel:'Reverter finalização'});if(!reason||!contextMatches(request))return;try{await api(scope(`/tax-ledgers/${a.id}/reverse`,cid),{method:'POST',context:request,body:{period:p,reason}});changed();notify('Finalização revertida. As bases podem ser revisadas.');}catch(e){notify(e.message,'error');}}
function chooseItems(e,event){e.item_indices=Array.from(event.target.selectedOptions).map(o=>Number(o.value));}
onUnmounted(()=>{generation++;if(state.editor?.owner==='assessment')state.editor=null;});
</script>
<template><div class="view assessments-view"><header class="view-heading"><div><div class="eyebrow">CONFERÊNCIA TRIBUTÁRIA</div><h1>Apurações e ajustes</h1><p>Regras revisadas, bases explícitas e memória por tributo.</p></div><div class="actions"><button class="button outline" v-allow="['fiscal.assessments','create']" @click="open('adjustment')" :disabled="busy||loadingData||!!state.editor||!state.companyId||!!loadError||finalized">Novo ajuste</button><button class="button primary" v-allow="['fiscal.assessments','create']" @click="open()" :disabled="busy||loadingData||!!state.editor||!state.companyId||!!loadError||finalized">Preparar apuração</button></div></header><p class="message warning">A incidência, a composição da base e a admissibilidade do crédito dependem de revisão fiscal. Não há compensação entre tributos nem transmissão de obrigações.</p><p v-if="loadingData" class="message subtle" role="status">Carregando documentos, regras e memórias da competência…</p><p v-if="loadError" class="message error">{{loadError}}</p><label class="operation-month">Competência da apuração<select v-model="competence" :disabled="!!state.editor"><option v-for="m in 12" :value="state.period.slice(0,4)+'-'+String(m).padStart(2,'0')">{{String(m).padStart(2,'0')}}/{{state.period.slice(0,4)}} · {{state.yearLocks.fiscal?.[state.period.slice(0,4)+'-'+String(m).padStart(2,'0')]?.closed?'Fechada':'Aberta'}}</option></select></label><select v-model="tax" :disabled="!!state.editor||busy" aria-label="Tributo da pré-apuração"><option v-for="t in ['icms','ipi','iss','pis','cofins','ibs','cbs']" :key="t" :value="t">{{t.toUpperCase()}}</option></select><p v-if="finalized" class="message warning">Esta apuração está finalizada. Reverta a finalização antes de preparar outra memória.</p><section class="panel"><div class="table-scroll"><table><thead><tr><th>Memória</th><th>Tributo</th><th>Débitos</th><th>Créditos</th><th>A recolher</th><th>Crédito a transportar</th><th>Conferência</th><th></th></tr></thead><tbody><tr v-for="a in data.assessments.filter(a=>a.tax===tax)" :key="a.id"><td>#{{a.id}} · {{a.created_at}}</td><td>{{a.tax.toUpperCase()}}</td><td>{{money(a.snapshot.debit_cents)}}</td><td>{{money(a.snapshot.credit_cents)}}</td><td>{{money(a.snapshot.payable_cents)}}</td><td>{{money(a.snapshot.carry_credit_cents)}}</td><td><span class="badge" :class="a.stale?'warning':'success'">{{a.stale?'Origem alterada — refazer':'Origem preservada'}}</span></td><td><button class="button small" @click="detail=a">Ver memória</button><button v-if="!a.stale&&!data.ledgers.some(l=>!l.reversed_at&&l.tax===a.tax)" v-allow="['fiscal.assessments','book']" class="button small outline" @click="finalize(a)">Finalizar</button></td></tr></tbody></table></div></section><section class="panel"><div class="panel-heading"><h2>Apurações finalizadas</h2></div><div v-for="l in data.ledgers.filter(l=>l.tax===tax)" :key="l.id" class="assessment-entry"><strong>#{{l.id}} · {{l.tax.toUpperCase()}} · {{l.reversed_at?'Revertida':l.stale?'Origem alterada — revisar':'Finalizada'}}</strong><p>Crédito anterior {{money(l.opening_credit_cents)}} · a recolher {{money(l.payable_cents)}} · a transportar {{money(l.carry_credit_cents)}}</p><p>{{l.reason}} · {{l.created_by}} · {{l.created_at}}</p><div class="actions"><a v-allow="['fiscal.assessments','print']" class="button small" :href="`/api${scope(`/tax-ledgers/${l.id}/report`)}?format=pdf&purpose=print`" target="_blank" rel="noopener">Prévia / imprimir</a><a v-allow="['fiscal.assessments','export']" class="button small" :href="`/api${scope(`/tax-ledgers/${l.id}/report`)}?format=pdf`" download>PDF da memória</a><a v-allow="['fiscal.assessments','export']" class="button small" :href="`/api${scope(`/tax-ledgers/${l.id}/report`)}?format=xlsx`" download>Excel da memória</a><button v-if="!l.reversed_at" v-allow="['fiscal.assessments','reverse']" class="button small" @click="undoLedger(l)">Reverter finalização</button></div></div><p v-if="!data.ledgers.some(l=>l.tax===tax)" class="report-note">Nenhuma finalização deste tributo na competência.</p></section><h2>Ajustes da competência</h2><section class="panel"><table><thead><tr><th>Tributo</th><th>Natureza</th><th>Valor</th><th>Motivo / fonte</th><th></th></tr></thead><tbody><tr v-for="a in data.adjustments.filter(a=>a.tax===tax)" :key="a.id"><td>{{a.tax.toUpperCase()}}</td><td>{{a.kind==='debit'?'Débito':'Crédito'}}</td><td>{{money(a.amount_cents)}}</td><td>{{a.reason}} · {{a.source}}</td><td><span v-if="a.reversed_at">Estornado</span><button v-else class="button small" v-allow="['fiscal.assessments','reverse']" @click="reverse(a)">Estornar</button></td></tr></tbody></table></section>
<BaseModal v-if="show" :title="mode==='assessment'?'Preparar apuração':'Novo ajuste fiscal'" :subtitle="`${context.name} · ${context.period} · ${tax.toUpperCase()}`" wide @close="close"><p v-if="error" class="message error" role="alert">{{error}}</p><form id="assessment-form" @submit.prevent="mode==='assessment'?confer():save()"><fieldset :disabled="busy" style="border:0;padding:0;margin:0"><div class="form-grid"><label class="span-2">Fundamentação / fonte normativa *<textarea v-model="form.source" required/></label><template v-if="mode==='assessment'"><label>Responsável pela conferência *<input v-model="form.responsible" required/></label><label>Origem do saldo anterior<select v-model="form.opening_mode"><option value="previous">Transportar apuração do mês anterior</option><option value="manual">Implantação / saldo conferido manualmente</option></select></label><p v-if="form.opening_mode==='previous'" class="span-2">{{form.previous?.period}} · saldo do mesmo tributo: {{money(form.previous?.carry_credit_cents||0)}} · {{form.previous?.ledger_id?'Apuração #'+form.previous.ledger_id:'Sem finalização anterior; saldo zero'}} {{form.previous?.stale?'· Origem alterada: revisar':''}}</p><template v-else><label>Saldo credor anterior deste tributo<input v-model="form.opening_credit" inputmode="decimal"/></label><label>Fundamento do saldo manual<input v-model="form.opening_reason" required/></label></template></template><template v-else><label>Categoria do ajuste<select v-model="form.category" @change="form.kind=['debit','reverse_credit'].includes(form.category)?'debit':['credit','reverse_debit'].includes(form.category)?'credit':form.kind"><option value="other">Outro ajuste conferido</option><option value="debit">Débito</option><option value="credit">Crédito</option><option value="reverse_debit">Estorno de débito</option><option value="reverse_credit">Estorno de crédito</option></select></label><label>Natureza<select v-model="form.kind"><option value="debit">Débito</option><option value="credit">Crédito</option></select></label><label>Valor (R$) *<input v-model="form.amount" required/></label><label class="span-2">Justificativa *<input v-model="form.reason" required/></label></template></div><template v-if="mode==='assessment'"><p v-if="!rules.length" class="message warning">Cadastre e revise uma regra deste tributo em Parâmetros antes de apurar.</p><p>{{selectedCount}} bases selecionadas de {{form.entries.length}}. Débito/crédito e fundamento exigem conferência; total da nota não é sugerido como base.</p><div class="form-grid three"><label>Natureza comum<select aria-label="Natureza comum" v-model="common.effect"><option value="">Não alterar</option><option value="debit">Débito</option><option value="credit">Crédito conferido</option></select></label><label>Regra comum<select aria-label="Regra comum" v-model.number="common.rule_id"><option value="">Não alterar</option><option v-for="r in rules" :key="r.id" :value="r.id">{{r.name}} · {{r.rate}}%</option></select></label><label>Fundamento comum<input v-model="common.reason"/></label><button type="button" class="button outline" @click="applyCommon">Aplicar às bases selecionadas</button><button type="button" class="button outline" @click="balanceOnly">Só ajustes e saldo anterior</button></div><div class="actions"><button type="button" class="button small" :disabled="page===1" @click="page--">Anterior</button><span>Página {{page}} de {{pageCount}} · até 50 bases por página</span><button type="button" class="button small" :disabled="page>=pageCount" @click="page++">Próxima</button></div><div v-for="(e,i) in visibleEntries" :key="(page-1)*50+i" class="assessment-entry form-grid three"><label class="check-label span-3"><input v-model="e.selected" type="checkbox"/>Incluir esta base no cálculo</label><label>Documento escriturado<select v-model.number="e.document_id" :required="e.selected!==false" @change="changeDocument(e)"><option value="">Selecione</option><option v-for="d in data.documents.filter(d=>d.status==='booked'&&!d.book_cancellation)" :key="d.id" :value="d.id">{{d.number}} · {{d.partner_name}}</option></select></label><label>Regra revisada<select v-model.number="e.rule_id" :required="e.selected!==false"><option value="">Selecione</option><option v-for="r in rules" :key="r.id" :value="r.id">{{r.name}} · {{r.rate}}% · {{r.source}}</option></select></label><label>Natureza<select v-model="e.effect"><option value="">Confira a natureza</option><option value="debit">Débito</option><option value="credit">Crédito conferido</option></select></label><label class="span-3">Itens abrangidos (opcional; sem seleção abrange o documento)<select multiple :value="e.item_indices||[]" @change="chooseItems(e,$event)"><option v-for="(item,index) in data.documents.find(d=>d.id===e.document_id)?.items||[]" :key="index" :value="index">{{index+1}} · {{item.description}} · NCM {{item.ncm}} · {{item.total}}</option></select></label><label>Base conferida (R$)<input v-model="e.base" :required="e.selected!==false"/></label><label class="span-2">Fundamento da base / direito ao crédito<input v-model="e.reason" :required="e.selected!==false"/></label><button type="button" class="text-button" @click="form.entries.splice((page-1)*50+i,1);page=Math.min(page,pageCount)">Remover base</button></div><button type="button" class="button outline" :disabled="form.entries.length>=1000" @click="form.no_movement_confirmed=false;form.entries.push({document_id:'',rule_id:'',effect:'',base:'',reason:'',item_indices:[],selected:true})">Adicionar base conferida</button><label v-if="!selectedCount" class="check-label"><input v-model="form.no_movement_confirmed" type="checkbox"/>Confirmei a ausência de bases neste cenário; apurar somente ajustes e saldo anterior.</label></template><section v-if="preview" class="message success" aria-label="Prévia do cálculo"><h3>Conferência antes de salvar</h3><p>Débitos {{money(preview.snapshot.debit_cents)}} · créditos {{money(preview.snapshot.credit_cents)}} · saldo anterior {{money(preview.snapshot.opening_credit_cents)}} · a recolher {{money(preview.snapshot.payable_cents)}} · a transportar {{money(preview.snapshot.carry_credit_cents)}}</p><p>{{preview.coverage.included_documents}} documentos incluídos de {{preview.coverage.booked_documents}} escriturados; {{preview.coverage.omitted_document_ids.length}} omitidos; {{preview.coverage.partial_document_ids.length}} com itens parciais; {{preview.coverage.pending_documents}} pendentes. A prévia não salva nem finaliza.</p><p v-if="preview.coverage.omitted_document_ids.length">Omitidos: {{preview.coverage.omitted_document_ids.join(', ')}}</p><p v-if="preview.coverage.partial_document_ids.length">Itens parciais: {{preview.coverage.partial_document_ids.join(', ')}}</p></section></fieldset></form><template #footer><button class="button" @click="close" :disabled="busy">Cancelar</button><button class="button outline" v-if="mode==='assessment'" type="submit" form="assessment-form" :disabled="busy">Conferir cálculo</button><button class="button primary" v-if="mode==='assessment'" type="button" @click="save" :disabled="busy||!preview">Salvar memória conferida</button><button v-else class="button primary" type="submit" form="assessment-form" :disabled="busy">Registrar ajuste</button></template></BaseModal>
<BaseModal v-if="detail" title="Memória de cálculo" wide @close="detail=null"><p>{{detail.source}} · Conferência: {{detail.responsible}}</p><p>{{detail.snapshot.scope_note}}</p><p>Saldo anterior: {{money(detail.snapshot.opening_credit_cents)}} · a recolher: {{money(detail.snapshot.payable_cents)}} · a transportar: {{money(detail.snapshot.carry_credit_cents)}}</p><div class="table-scroll"><table><thead><tr><th>Documento / versão</th><th>Regra / versão</th><th>Base</th><th>Alíquota</th><th>Resultado</th><th>Natureza</th><th>Fundamento</th></tr></thead><tbody><tr v-for="(e,i) in detail.snapshot.entries" :key="i"><td>{{e.document_number}} · v{{e.document_version}}</td><td>#{{e.rule_id}} · v{{e.rule_version}}</td><td>{{money(e.base_cents)}}</td><td>{{e.rate}}%</td><td>{{money(e.result_cents)}}</td><td>{{e.effect==='debit'?'Débito':'Crédito'}}</td><td>{{e.reason}} · {{e.source}}</td></tr></tbody></table></div><p>Arredondamento: metade para cima, em centavos, por base conferida.</p><small class="wrap-anywhere">Identificador da memória: {{detail.fingerprint}}</small><template #footer><button class="button" @click="detail=null">Fechar</button></template></BaseModal></div></template>
